import java.awt.*;class Book{    String title;    String author;    int price;    Book(String title, String author, int price){        this.title = title;        this.author = author;        this.price = price;    }    void displayDetails(){        System.out.println("Title: " + title);        System.out.println("Author: " + author);        System.out.println("Price: " + price);    }}public class Books {    public static void main(String[] args) {        Book b1 = new Book("Gulliver Travels", "abc", 500);        b1.displayDetails();    }}